CREATE COLUMN TABLE "TEST_AP"."OWWT" ("ID" INTEGER CS_INT NOT NULL , "Category" NVARCHAR(40) NOT NULL , "Layout" NCLOB MEMORY THRESHOLD 1000, "Action" NCLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("ID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OWWT_CATEGORY" ON "TEST_AP"."OWWT" ( "Category" ASC )